import{_ as e,o as t,c as i,a4 as n}from"./chunks/framework.BRzJ4ijD.js";const h=JSON.parse('{"title":"IP / 路由","description":"","frontmatter":{},"headers":[],"relativePath":"networking/ip/index.md","filePath":"networking/ip/README.md","lastUpdated":1788475713000}'),l={name:"networking/ip/index.md"};function s(o,a,r,p,c,P){return t(),i("div",null,[...a[0]||(a[0]=[n(`<h1 id="ip-路由" tabindex="-1">IP / 路由 <a class="header-anchor" href="#ip-路由" aria-label="Permalink to &quot;IP / 路由&quot;">​</a></h1><h2 id="tl-dr" tabindex="-1">TL;DR <a class="header-anchor" href="#tl-dr" aria-label="Permalink to &quot;TL;DR&quot;">​</a></h2><p>IP 是 TCP/IP 协议栈&quot;L3 不可靠、全互联、尽力交付 (best-effort)&quot;的抽象。它把所有底层物理介质屏蔽掉，给上层提供 32 位地址（v4）/ 128 位地址（v6）加路由表查询的能力。这一节读完后你应该能看懂 <code>ip route get</code>、调试路由黑洞、解释 privacy extension、回答 BGP vs OSPF 收敛速度差异。</p><h2 id="思维链" tabindex="-1">思维链 <a class="header-anchor" href="#思维链" aria-label="Permalink to &quot;思维链&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>应用 -&gt; socket -&gt; TCP -&gt; IP -&gt; Ethernet</span></span>
<span class="line"><span>                   ↑</span></span>
<span class="line"><span>              ip_route_input() 查路由表</span></span>
<span class="line"><span>              ↓</span></span>
<span class="line"><span>            下一跳 -&gt; ARP/ND -&gt; 帧</span></span></code></pre></div><p>DNS 给出名 <code>api.example.com</code> -&gt; 通过 socket 给应用 IP -&gt; IP 层判断目标路由：</p><ul><li>同子网：直接 ARP 解出 MAC，封装帧</li><li>跨网段：查路由表 -&gt; 下一跳 -&gt; ARP 下一跳 -&gt; 转发</li></ul><p>每一跳路由器都重复查表 -&gt; 改 TTL -&gt; 重算 checksum -&gt; 转发。一台路由器每秒可以处理 10M-100M 包（有 TCAM 卸载可达线速；软件路由只有 1M-10M pps）。</p><h2 id="这一节要回答的问题" tabindex="-1">这一节要回答的问题 <a class="header-anchor" href="#这一节要回答的问题" aria-label="Permalink to &quot;这一节要回答的问题&quot;">​</a></h2><ol><li>IPv4 头部 20 字节每个字段有什么用？为什么 IPv6 去掉了 checksum 反而更快？</li><li>ICMP 在分片 / PMTUD / traceroute 里到底做了什么？为什么大量 IDC 把 ICMP 整体黑洞掉 PMTUD 必崩？</li><li>ARP 一秒钟怎么解析、为什么 ARP cache 5 分钟后掉；邻居发现 NDP 比它强在哪儿？</li><li>DHCP 跨网段必须 relay agent + Option 82，Option 82 是怎么把 client 接入端口传给集中服务器的？</li><li>OSPF 是什么类型协议，为什么 ISP 不喜欢在 AS 大规模用 OSPF 而用 IS-IS？</li><li>BGP 是什么类型协议，为什么能承载全球 ~1.1M v4 前缀，路径属性 AS_PATH / LOCAL_PREF / MED / communities 怎么决策？</li><li>NAT 在 conntrack 表里吃 1 KB / 流，1M 表 = 1 GB RAM；单体 NAT 能撑多少 concurrent？运营商用 CGN 是怎么后向退化到 Symmetric NAT 影响 P2P？</li></ol><h2 id="这一节骨架" tabindex="-1">这一节骨架 <a class="header-anchor" href="#这一节骨架" aria-label="Permalink to &quot;这一节骨架&quot;">​</a></h2><ul><li><a href="./ipv6">IPv4 / IPv6 / ICMP</a>：头部字段、扩展头、邻居发现、SLAAC、ICMP 与 PMTUD 关键</li><li><a href="./arp-dhcp">DHCP / ARP / NDP</a>：地址解析、地址分配、跨网段 relay、安全陷阱</li><li><a href="./bgp-ospf">BGP / OSPF 路由</a>：链路状态 vs 路径向量、收敛对比、生产场景选择</li><li><a href="./nat">NAT 与 conntrack</a>：5 元组 conntrack 表、Cone vs Symmetric NAT、P2P 打洞失败根因</li><li><a href="./dns">DNS</a>：递归/权威分层、TTL 与缓存、CDN 调度、DNSSEC / DoH / HTTPDNS</li></ul>`,12)])])}const u=e(l,[["render",s]]);export{h as __pageData,u as default};
